Integration TestingIntegration testing assesses the interactions between various components or modules of the application. This approach ensures that different parts of the system work harmoniously when integrated, detecting any compatibility or communication issues. Integration testing checks interactions between components or modules to ensure they work together correctly. You can use mock objects to simulate external dependencies. Use getMockBuilder or createMock to create mocks.

Example: This example shows the Integration Testing. 



            PHP

    <?php
require_once 'PaymentGateway.php';
require_once 'PaymentProcessor.php'; 

use PHPUnit\Framework\TestCase;

class PaymentProcessingIntegrationTest extends TestCase {
    public function testPaymentProcessingSuccess() {
        $mockGateway = $this->createMock
                      (PaymentGateway::class);
        $mockGateway->method('processPayment')
            ->willReturn(true);

        $processor = new PaymentProcessor($mockGateway);
        $processed = $processor->processPayment(100.00,
                                                'visa');
        $this->assertTrue($processed);
    }

    public function testPaymentProcessingFailure() {
        $mockGateway = $this->createMock 
                      (PaymentGateway::class);
        $mockGateway->method('processPayment')
            ->willReturn(false);

        $processor = new PaymentProcessor($mockGateway);
        $processed = $processor->processPayment(50.00, 'amex');
        $this->assertFalse($processed); 
    }
}



            PHP

    <?
class PaymentProcessor {
    protected $gateway;

    public function __construct(PaymentGateway $gateway) {
        $this->gateway = $gateway;
    }

    public function processPayment($amount, $cardType) {
        return $this->gateway->processPayment($amount,
                                              $cardType);
    }
}



            PHP

    <?
class PaymentGateway {
    public function processPayment($amount, $cardType) {
        // Simulate payment processing logic
        if ($amount > 0 && in_array($cardType, ['visa',
                                              'mastercard'])) {
            return true;
        } else {
            return false;
        }
    }
}

